begin;
do $constraint$ declare d text;begin select pg_get_constraintdef(oid) into d from pg_constraint where conrelid='public.cb_planning_notifications'::regclass and conname='cb_planning_notifications_source_kind_check';if strpos(d,'''document''')=0 then alter table public.cb_planning_notifications drop constraint cb_planning_notifications_source_kind_check;execute 'alter table public.cb_planning_notifications add constraint cb_planning_notifications_source_kind_check CHECK (('||substring(d from 8 for length(d)-8)||') OR source_kind = ''document'')';end if;end;$constraint$;
create or replace function public.cb_document_notice_access(p_user uuid,p_project uuid,p_doc uuid) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.cb_documents d where d.id=p_doc and d.project_id=p_project and d.deleted_at is null and public.cb_collab_user_access(p_user,p_project,'read') and not exists(select 1 from public.cb_projects where id=p_project and archived_at is not null) and (d.created_by=p_user or exists(select 1 from public.cb_document_access where document_id=d.id and user_id=p_user)))$$;
create or replace function public.cb_document_notice_visible(p_user uuid,p_project uuid,p_doc uuid,p_date date,p_category text,p_kind text) returns boolean language sql stable security definer set search_path='' as $$select public.cb_document_notice_access(p_user,p_project,p_doc) and not exists(select 1 from public.cb_planning_preferences where user_id=p_user and not p_category=any(categories)) and (p_category='assignments' and p_kind='document_updated' or p_category='deadlines' and exists(select 1 from public.cb_documents d where d.id=p_doc and d.created_by=p_user and d.data->>'reminder'='true' and d.status<>'Archived' and ((d.status<>'Signed' and d.data->>'deadline'=p_date::text) or d.data->>'expiry'=p_date::text) and p_date<=public.cb_decision_local_day(p_user)+7 and p_kind='document_due:'||p_date::text))$$;
do $wrap$ begin
 if to_regprocedure('public.cb_planning_can_view_before_documents(uuid,uuid,text,uuid)') is null then alter function public.cb_planning_can_view(uuid,uuid,text,uuid) rename to cb_planning_can_view_before_documents;end if;
 if to_regprocedure('public.cb_planning_notice_visible_before_documents(uuid,text,uuid,date,text,text)') is null then alter function public.cb_planning_notice_visible(uuid,text,uuid,date,text,text) rename to cb_planning_notice_visible_before_documents;end if;
 if to_regprocedure('public.cb_generate_planning_reminders_before_documents(uuid)') is null then alter function public.cb_generate_planning_reminders(uuid) rename to cb_generate_planning_reminders_before_documents;end if;
end;$wrap$;
create or replace function public.cb_planning_can_view(p_user uuid,p_project uuid,p_kind text,p_source uuid) returns boolean language sql stable security definer set search_path='' as $$select case when p_kind='document' then public.cb_document_notice_access(p_user,p_project,p_source) else public.cb_planning_can_view_before_documents(p_user,p_project,p_kind,p_source) end$$;
create or replace function public.cb_planning_notice_visible(p_project uuid,p_kind text,p_source uuid,p_date date,p_category text,p_notice_kind text) returns boolean language sql stable security definer set search_path='' as $$select case when p_kind='document' then public.cb_document_notice_visible(auth.uid(),p_project,p_source,p_date,p_category,p_notice_kind) else public.cb_planning_notice_visible_before_documents(p_project,p_kind,p_source,p_date,p_category,p_notice_kind) end$$;
drop policy if exists planning_inbox_own on public.cb_planning_notifications;create policy planning_inbox_own on public.cb_planning_notifications for select to authenticated using(user_id=auth.uid() and public.cb_planning_notice_visible(project_id,source_kind,source_id,source_date,category,kind));
create or replace function public.cb_document_changed() returns trigger language plpgsql security definer set search_path='' as $$
declare u uuid;begin
 for u in select created_by from public.cb_documents where id=new.id union select user_id from public.cb_document_access where document_id=new.id loop
 if u is distinct from auth.uid() and public.cb_document_notice_access(u,new.project_id,new.id) then perform public.cb_queue_planning_notice(u,new.project_id,'assignments','document_updated','document',new.id,null,'A shared document has an update','Sign in to review the document, its comments or approval status.','document:'||new.id||':'||floor(extract(epoch from now())/600));end if;
 end loop;return new;
end;$$;
drop trigger if exists cb_document_changed on public.cb_documents;create trigger cb_document_changed after insert or update on public.cb_documents for each row execute function public.cb_document_changed();
create or replace function public.cb_generate_document_reminders(p_user uuid default null) returns integer language plpgsql security definer set search_path='' as $$
declare r record;n integer=0;begin
 for r in select d.id,d.project_id,d.created_by as recipient,dates.value::date as due from public.cb_documents d cross join lateral (values (nullif(d.data->>'deadline','')),(nullif(d.data->>'expiry',''))) dates(value) where dates.value is not null and d.data->>'reminder'='true' and (p_user is null or d.created_by=p_user) and d.deleted_at is null and d.status<>'Archived' and (d.status<>'Signed' or dates.value=nullif(d.data->>'expiry','')) and public.cb_document_notice_access(d.created_by,d.project_id,d.id) and dates.value::date<=public.cb_decision_local_day(d.created_by)+7 loop
 perform public.cb_queue_planning_notice(r.recipient,r.project_id,'deadlines','document_due:'||r.due,'document',r.id,r.due,'A document deadline needs your attention','Review the document deadline or expiry date.','document-due:'||r.id||':'||r.due);n=n+1;end loop;return n;
end;$$;
create or replace function public.cb_generate_planning_reminders(p_user uuid default null) returns integer language plpgsql security definer set search_path='' as $$begin return public.cb_generate_planning_reminders_before_documents(p_user)+public.cb_generate_document_reminders(p_user);end;$$;
create or replace function public.cb_document_notice_target(p_notice uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$declare n public.cb_planning_notifications;begin select * into n from public.cb_planning_notifications where id=p_notice and user_id=auth.uid() and source_kind='document';if n.id is null or not public.cb_document_notice_visible(auth.uid(),n.project_id,n.source_id,n.source_date,n.category,n.kind) then raise exception 'Document update is no longer available' using errcode='42501';end if;return jsonb_build_object('project',n.project_id,'document',n.source_id);end;$$;
do $digest$ declare b text;begin if to_regprocedure('public.cb_planning_digest_items(uuid,timestamptz,timestamptz)') is not null then b=pg_get_functiondef('public.cb_planning_digest_items(uuid,timestamptz,timestamptz)'::regprocedure);if strpos(b,'public.cb_document_notice_visible')=0 then b=replace(b,'n.user_id=p_user','n.user_id=p_user and (n.source_kind<>''document'' or public.cb_document_notice_visible(p_user,n.project_id,n.source_id,n.source_date,n.category,n.kind))');b=replace(b,'else public.cb_planning_can_view(p_user,n.project_id,n.source_kind,n.source_id)','when n.source_kind=''document'' then public.cb_document_notice_visible(p_user,n.project_id,n.source_id,n.source_date,n.category,n.kind) else public.cb_planning_can_view(p_user,n.project_id,n.source_kind,n.source_id)');execute b;end if;end if;end;$digest$;
revoke all on function public.cb_document_notice_access(uuid,uuid,uuid),public.cb_document_notice_visible(uuid,uuid,uuid,date,text,text),public.cb_document_changed(),public.cb_generate_document_reminders(uuid),public.cb_generate_planning_reminders(uuid),public.cb_planning_can_view_before_documents(uuid,uuid,text,uuid),public.cb_planning_notice_visible_before_documents(uuid,text,uuid,date,text,text),public.cb_generate_planning_reminders_before_documents(uuid),public.cb_planning_can_view(uuid,uuid,text,uuid),public.cb_document_notice_target(uuid) from public,anon,authenticated;
grant execute on function public.cb_document_notice_target(uuid) to authenticated;revoke all on function public.cb_planning_notice_visible(uuid,text,uuid,date,text,text) from public,anon;grant execute on function public.cb_planning_notice_visible(uuid,text,uuid,date,text,text) to authenticated;
do $refresh$ declare s text;b text;begin foreach s in array array['public.cb_queue_planning_notice(uuid,uuid,text,text,text,uuid,date,text,text,text)','public.cb_planning_inbox()','public.cb_read_planning_notifications(uuid,boolean)','public.cb_process_planning_email()'] loop if to_regprocedure(s) is not null then b=pg_get_functiondef(to_regprocedure(s));execute b;end if;end loop;end;$refresh$;
